/* @autogenerated */
import { TestBed, fakeAsync, tick } from '@angular/core/testing';
import { HttpErrorResponse, HttpRequest } from '@angular/common/http';
import { NavigationEnd, Router } from '@angular/router';
import { OAuthService } from 'angular-oauth2-oidc';
import { Subject, of } from 'rxjs';
import { ConfirmDialogService } from '@shared/toolkit/dialog/confirm-dialog.service';
import { NotifyService } from '@shared/toolkit/notify/notify.service';
import { StepUpService } from './step-up.service';

const PENDING_KEY = 'stepup.pending';

describe('StepUpService', () => {
  let service: StepUpService;
  let events: Subject<any>;
  let oauth: any;
  let confirm: jasmine.SpyObj<ConfirmDialogService>;
  let notify: jasmine.SpyObj<NotifyService>;
  let router: any;
  const error = new HttpErrorResponse({ status: 401 });
  const post = new HttpRequest('POST', '/api/clients', { secretOauth: 's3cr3t' });

  beforeEach(() => {
    sessionStorage.removeItem(PENDING_KEY);
    events = new Subject<any>();
    oauth = { events, state: '', initCodeFlow: jasmine.createSpy('initCodeFlow') };
    confirm = jasmine.createSpyObj<ConfirmDialogService>('ConfirmDialogService', ['confirm']);
    notify = jasmine.createSpyObj<NotifyService>('NotifyService', ['success', 'info', 'error']);
    router = {
      url: '/access/oauth-client/new',
      navigated: true,
      events: new Subject<any>(),
      navigateByUrl: jasmine.createSpy('navigateByUrl').and.returnValue(Promise.resolve(true)),
    };
    TestBed.configureTestingModule({
      providers: [
        { provide: OAuthService, useValue: oauth },
        { provide: ConfirmDialogService, useValue: confirm },
        { provide: NotifyService, useValue: notify },
        { provide: Router, useValue: router },
      ],
    });
    service = TestBed.inject(StepUpService);
    service.listen();
  });

  afterEach(() => sessionStorage.removeItem(PENDING_KEY));

  describe('start()', () => {
    it('asks for confirmation and redirects without storing the request body', () => {
      confirm.confirm.and.returnValue(of(true));
      const next = jasmine.createSpy('next');
      const done = jasmine.createSpy('done');

      service.start(post, error, 'urn:mfa', '300').subscribe({ next, error: done, complete: done });

      expect(confirm.confirm).toHaveBeenCalledWith(jasmine.objectContaining({ messageKey: 'identity.stepUp.message' }));
      expect(oauth.initCodeFlow).toHaveBeenCalledOnceWith('stepup', { acr_values: 'urn:mfa', max_age: '300' });
      const stored = sessionStorage.getItem(PENDING_KEY)!;
      expect(JSON.parse(stored)).toEqual({
        method: 'POST',
        url: '/api/clients',
        returnUrl: '/access/oauth-client/new',
      });
      expect(stored).not.toContain('s3cr3t');
      expect(next).not.toHaveBeenCalled();
      expect(done).not.toHaveBeenCalled();
    });

    it('fails with the original error when the user cancels', () => {
      confirm.confirm.and.returnValue(of(false));
      const errorSpy = jasmine.createSpy('error');

      service.start(post, error).subscribe({ error: errorSpy });

      expect(errorSpy).toHaveBeenCalledWith(error);
      expect(oauth.initCodeFlow).not.toHaveBeenCalled();
      expect(sessionStorage.getItem(PENDING_KEY)).toBeNull();
    });

    it('shows a single dialog and redirects once for concurrent requests', () => {
      const answer = new Subject<boolean>();
      confirm.confirm.and.returnValue(answer);

      service.start(post, error).subscribe();
      service.start(new HttpRequest('GET', '/api/other'), error).subscribe();
      answer.next(true);
      answer.complete();

      expect(confirm.confirm).toHaveBeenCalledTimes(1);
      expect(oauth.initCodeFlow).toHaveBeenCalledTimes(1);
    });
  });

  describe('on return from the provider', () => {
    const store = (method: string) =>
      sessionStorage.setItem(PENDING_KEY, JSON.stringify({ method, url: '/api/x', returnUrl: '/back' }));

    it('navigates back and asks to repeat a write operation', fakeAsync(() => {
      store('POST');
      oauth.state = 'stepup';

      events.next({ type: 'token_received' });
      tick();

      expect(router.navigateByUrl).toHaveBeenCalledWith('/back');
      expect(notify.info).toHaveBeenCalledWith('identity.stepUp.repeat');
      expect(sessionStorage.getItem(PENDING_KEY)).toBeNull();
    }));

    it('navigates back and confirms the verification for a read', fakeAsync(() => {
      store('GET');
      oauth.state = 'stepup';

      events.next({ type: 'token_received' });
      tick();

      expect(router.navigateByUrl).toHaveBeenCalledWith('/back');
      expect(notify.success).toHaveBeenCalledWith('identity.stepUp.verified');
    }));

    it('waits for the initial navigation before going back', fakeAsync(() => {
      store('POST');
      oauth.state = 'stepup';
      router.navigated = false;

      events.next({ type: 'token_received' });
      tick();
      expect(router.navigateByUrl).not.toHaveBeenCalled();

      router.events.next(new NavigationEnd(1, '/callback', '/callback'));
      tick();
      expect(router.navigateByUrl).toHaveBeenCalledWith('/back');
    }));

    it('ignores tokens that do not come from a step-up', fakeAsync(() => {
      store('POST');
      oauth.state = '';

      events.next({ type: 'token_received' });
      tick();

      expect(router.navigateByUrl).not.toHaveBeenCalled();
      expect(sessionStorage.getItem(PENDING_KEY)).toBeNull();
    }));
  });
});
